class LmdbBulkParserRegressionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:s");
	private static final IRI PREDICATE = VF.createIRI("urn:p");

	@TempDir
	Path temporaryDirectory;

	@Test
	void reopensExactEscapedLiteralTermsForEveryParserAndStagingMode() throws IOException {
		String input = "<urn:s> <urn:p> \"a\\nb\"^^<urn:\\u0064> .\n"
				+ "<urn:s> <urn:p> \"" + "x".repeat(2_049) + "\\u00E9\"^^<urn:" + "d".repeat(4_097) + "\\u0065> .\n"
				+ "<urn:s> <urn:p> <<( <urn:s> <urn:p> \"a\\tb\"^^<urn:\\u0064> )>> .\n";
		Set<Statement> expected = Set.of(
				VF.createStatement(SUBJECT, PREDICATE, VF.createLiteral("a\nb", VF.createIRI("urn:d"))),
				VF.createStatement(SUBJECT, PREDICATE,
						VF.createLiteral("x".repeat(2_049) + "é", VF.createIRI("urn:" + "d".repeat(4_097) + "e"))),
				VF.createStatement(SUBJECT, PREDICATE,
						VF.createTripleTerm(SUBJECT, PREDICATE, VF.createLiteral("a\tb", VF.createIRI("urn:d")))));
		for (RDFFormat format : List.of(RDFFormat.NTRIPLES, RDFFormat.NQUADS)) {
			for (LmdbBulkLoader.ParserMode mode : LmdbBulkLoader.ParserMode.values()) {
				for (int workers : List.of(1, 3)) {
					Path target = target("literal", format, mode, workers);
					LmdbBulkLoader.Result result = loader(target, mode, workers)
							.load(new ByteArrayInputStream(input.getBytes(UTF_8)), "urn:test:", format);
					assertEquals(3L, result.parsedStatements());
					assertEquals(expected, read(target));
					assertEquals(expected, read(target));
				}
			}
		}
	}

	@Test
	void reopensBlankNodeBoundariesAndPreservesDocumentIdentity() throws IOException {
		for (RDFFormat format : List.of(RDFFormat.NTRIPLES, RDFFormat.NQUADS)) {
			String graph = RDFFormat.NQUADS.equals(format) ? " _:g.h" : "";
			String input = "_:a.b <urn:p> _:c..d" + graph + ".\n"
					+ "_:c..d <urn:p> _:a.b" + graph + ".\r\n";
			Set<Statement> expected = Set.of(
					VF.createStatement(VF.createBNode("a.b"), PREDICATE, VF.createBNode("c..d"),
							RDFFormat.NQUADS.equals(format) ? VF.createBNode("g.h") : null),
					VF.createStatement(VF.createBNode("c..d"), PREDICATE, VF.createBNode("a.b"),
							RDFFormat.NQUADS.equals(format) ? VF.createBNode("g.h") : null));
			for (LmdbBulkLoader.ParserMode mode : LmdbBulkLoader.ParserMode.values()) {
				for (int workers : List.of(1, 3)) {
					Path target = target("bnode", format, mode, workers);
					loader(target, mode, workers).load(new ByteArrayInputStream(input.getBytes(UTF_8)), "urn:test:",
							format);
					Set<Statement> first = read(target);
					assertTrue(Models.isomorphic(expected, first));
					assertEquals(first, read(target));
					if (mode != LmdbBulkLoader.ParserMode.RIO) {
						assertEquals(expected, first);
					}
				}
			}
		}
	}

	@Test
	void scopesUnicodeBlankNodesIndependentlyAcrossParallelFiles() throws IOException {
		assertScopedFiles("é.a\u0300");
	}

	@Test
	void scopesRdf11ColonBlankNodesIndependentlyAcrossParallelFiles() throws IOException {
		assertScopedFiles(":a.b:c:");
	}

	private void assertScopedFiles(String label) throws IOException {
		String input = "_:" + label + " <urn:p> _:" + label + " _:" + label + ".\n";
		Path first = temporaryDirectory.resolve("first.nq");
		Path second = temporaryDirectory.resolve("second.nq");
		Files.writeString(first, input);
		Files.writeString(second, input);
		Set<Statement> expected = new HashSet<>();
		for (int index = 0; index < 2; index++) {
			String scoped = "f" + index + "/" + label;
			expected.add(VF.createStatement(VF.createBNode(scoped), PREDICATE, VF.createBNode(scoped),
					VF.createBNode(scoped)));
		}
		for (LmdbBulkLoader.ParserMode mode : List.of(LmdbBulkLoader.ParserMode.FAST, LmdbBulkLoader.ParserMode.AUTO)) {
			for (int workers : List.of(1, 3)) {
				Path target = target("unicode", RDFFormat.NQUADS, mode, workers);
				loader(target, mode, workers)
						.load(List.of(new LmdbBulkLoader.PathInput(first, RDFFormat.NQUADS, "urn:test:"),
								new LmdbBulkLoader.PathInput(second, RDFFormat.NQUADS, "urn:test:")));
				assertEquals(expected, read(target));
				assertEquals(expected, read(target));
			}
		}
	}

	private Path target(String name, RDFFormat format, LmdbBulkLoader.ParserMode mode, int workers) {
		return temporaryDirectory.resolve(name + "-" + format.getName() + "-" + mode + "-" + workers);
	}

	private static LmdbBulkLoader loader(Path target, LmdbBulkLoader.ParserMode mode, int workers) {
		return LmdbBulkLoader.builder(target, new LmdbStoreConfig("spoc,psoc"))
				.parserMode(mode)
				.partitionCount(4)
				.workers(workers)
				.maxOpenFiles(32)
				.memoryBudgetBytes(64L * 1024 * 1024)
				.stagingBlockBytes(4 * 1024)
				.build();
	}

	private static Set<Statement> read(Path target) {
		SailRepository repository = new SailRepository(
				new LmdbStore(target.toFile(), new LmdbStoreConfig("spoc,psoc")));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection();
				var statements = connection.getStatements(null, null, null, false)) {
			return statements.stream().collect(Collectors.toSet());
		} finally {
			repository.shutDown();
		}
	}
}
